// Pulled into the generated `public/sw.js` via next.config.js's
// `importScripts` option (NOT edited manually -- that file is
// auto-generated by next-pwa/workbox on every production build). A plain
// static file rather than part of the webpack/InjectManifest pipeline on
// purpose: GenerateSW mode (this app's existing setup) already registers
// all of this app's caching routes correctly, and reimplementing that in
// a custom InjectManifest source file just to add push handling would
// risk silently losing/drifting from that existing behavior. `importScripts`
// is the one additive hook GenerateSW offers for exactly this case.

self.addEventListener('push', (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    // Not valid JSON -- fall through to the generic title/body below
    // rather than throwing out of the event handler.
  }

  const title = payload.title || 'CoreFit';
  const body = payload.body || '';
  const conversationId = payload.conversationId || null;

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      icon: '/icons/icon-192x192.png',
      badge: '/icons/icon-192x192.png',
      data: { conversationId },
    }),
  );
});

// Focuses an already-open CoreFit tab on the conversation rather than
// always opening a new one, the same "reuse an existing window" pattern
// most chat apps use for their own push notifications.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const conversationId = event.notification.data && event.notification.data.conversationId;
  const targetPath = conversationId ? `/messages/${conversationId}` : '/messages';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) {
          client.navigate(targetPath);
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetPath);
      }
    }),
  );
});
